import { ApprovalMode } from '../policy/types.js';

/**
 * Returns a human-readable description for the given approval mode.
 */
export function getApprovalModeDescription(mode: ApprovalMode): string {
  switch (mode) {
    case ApprovalMode.DEFAULT:
      return 'Default mode (edits will require confirmation)';
    case ApprovalMode.AUTO_EDIT:
      return 'Auto-Edit mode (edits will be applied automatically)';
    case ApprovalMode.PLAN:
      return 'Plan mode (read-only planning)';
    case ApprovalMode.YOLO:
      return 'YOLO mode (all tool calls auto-approved)';
    default:
      return '';
  }
}

/**
 * Composes a message notifying the model that Plan Mode has been exited and the
 * approval mode has switched to `newMode`.
 *
 * @param newMode The approval mode being switched to.
 * @param manual Whether the user manually exited Plan Mode. Defaults to `false`,
 *   which indicates the plan was approved.
 */
export function getPlanModeExitMessage(
  newMode: ApprovalMode,
  manual = false,
): string {
  const description = getApprovalModeDescription(newMode);
  if (manual) {
    return `User has manually exited Plan Mode. Switching to ${description}.`;
  }
  return `Plan approved. Switching to ${description}.`;
}
